\begin{equation}
\hat{H} = -\frac{\hbar^2}{2m} \nabla^2 + V(x) ,
\hspace{0.5cm}
V(x)=
\begin{Bmatrix} 
-D & si\hspace{0.5cm}-A<x<A \\
0 & \textrm{en cualquier otro caso}
\end{Bmatrix}
\end{equation}

